/**
 * Expo config plugin that keeps `debuggableVariants = []` in the generated
 * android/app/build.gradle on every `expo prebuild`.
 *
 * WHY: React Native's Gradle plugin skips JS bundling for debuggable variants
 * (by default, `debug`). A debug APK built that way loads its JS from a Metro
 * dev server at runtime — it cannot run standalone in the field, and it fails
 * scripts/build-debug.sh's PAP-1650 assert ("EXPO_PUBLIC_SENTRY_DSN is set but
 * is absent from the packaged bundle") because assets/index.android.bundle
 * does not exist in the APK at all.
 *
 * b135..b153 carried this as a HAND-EDIT in the build host's shared
 * android/app/build.gradle ("Bundle JS in debug builds so APK works
 * standalone"). android/ is gitignored and regenerated by `expo prebuild`, so
 * the edit evaporated the moment a build ran from a fresh worktree — exactly
 * what happened to the b154 validation build on 2026-09-11 (PAP-1886), which
 * assembled clean, then refused to publish on the DSN assert. Same failure
 * family as PAP-1661: a setting whose only home is a regenerated directory.
 *
 * This plugin is the durable half. The assert in scripts/build-debug.sh stays
 * as the enforcement half: if this plugin is ever missing or the line is
 * reverted, the build fails loudly instead of shipping a Metro-dependent APK.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const LINE = 'debuggableVariants = []';
const ANCHOR = '// debuggableVariants = ["liteDebug", "prodDebug"]';
const INJECTED =
  '    ' + LINE + '  // Bundle JS in debug builds so APK works standalone (no Metro needed) — applied by mobile/plugins/withStandaloneDebugBundlePlugin.js (PAP-1886)';

module.exports = function withStandaloneDebugBundle(config) {
  return withAppBuildGradle(config, (cfg) => {
    const contents = cfg.modResults.contents;
    if (contents.includes(LINE)) return cfg; // idempotent
    if (!contents.includes(ANCHOR)) {
      throw new Error(
        'withStandaloneDebugBundle: could not find the debuggableVariants template ' +
          'comment in android/app/build.gradle — the Expo/RN template changed; ' +
          'update the plugin anchor.'
      );
    }
    cfg.modResults.contents = contents.replace(ANCHOR, ANCHOR + '\n' + INJECTED);
    return cfg;
  });
};
